n("עמוס", "עמוס בא מהשורש ע־מ־ס, שעניינו נשיאה של משא, כמו בפועל להעמיס ובמילה עומס. בתנ״ך עמוס הוא אחד מתריסר הנביאים, איש מתקוע שהיה רועה צאן ומגדל שקמים. בעברית של היום עמוס הוא גם מי שיש לו הרבה עבודה ועיסוקים.")
n("פתחי", "פתחי בא מהמילה הערבית פתח, פתיחה, שבערבית פירושה גם ניצחון וכיבוש, כמו של עיר שהשערים שלה נפתחו. השורש הערבי פ־ת־ח הוא אותו שורש של המילים העבריות פתח ופתיחה. מאותו שורש באה גם המילה הערבית מפתאח, מפתח, שדומה מאוד למילה העברית.")
n("רואן", "רואן הוא שם ערבי לבנות. בפירוש המקובל הוא שמו של מעיין בגן העדן, מקום של מים צלולים שמרווים את הצמא. מים מרווים הם דימוי ותיק בשירה הערבית, שנולדה בארצות המדבר, למה שמחייה ומרענן.")
n("רחים", "רחים היא מילה ערבית לרחום, למי שמרחם ומגלה חמלה. היא באה מהשורש ר־ח־ם, אותו שורש של המילים העבריות רחמים, רחום ורחמן. בערבית, כמו בעברית, רחום הוא גם אחד מכינויי האל.")
n("רחלי", "רחלי היא צורת חיבה של רחל, עם הסיומת ־י, שבעברית מוסיפה לשם נימה של קרבה וחיבה. רחל היא מילה עתיקה לכבשה, נקבת האיל, ובעברית המקראית היא מתארת כבשה מהעדר. באותה דרך נבנו צורות חיבה נוספות, כמו מירי ממרים.", ["רחל"])
n("אדיב", "אדיב היא מילה למי שנוהג בנימוס ובנעימות כלפי אחרים, בעברית ובערבית. בערבית אדיב פירושו גם איש ספר וכותב, ומאותו שורש באה המילה הערבית אדב, ספרות ונימוסים טובים. בעברית מאותו שורש באות גם המילים אדיבות ואדיבה.")
n("אדריס", "אדריס ואידריס הם שני כתיבים בעברית של אותו שם ערבי, שמו של נביא שמוזכר בקוראן. יש שקושרים את השם לשורש הערבי ד־ר־ס, שעניינו לימוד ועיון, כמו במילה מדרסה, בית ספר, ויש שרואים בו שם שהגיע לערבית משפה אחרת.", ["אידריס"])
n("אהבה", "אהבה היא אחת המילים העתיקות בעברית, והיא באה מהשורש א־ה־ב, שממנו באות גם המילים אוהב ואהוב. בתנ״ך המילה מופיעה פעמים רבות, ובמיוחד בשיר השירים, שכולו שירי אהבה. מאותו שורש נבנו גם השמות אהובה ואהוביה.")
n("אלחי", "אלחי מחבר את המילים אל וחי, ופירושו אלוהים חי. הצירוף אל חי מוכר מהשפה של התפילה והשירה, ובו חי פירושו קיים לתמיד. באותה דרך נבנו שמות נוספים שמחברים את המילה אל לתיאור, כמו אלעד ואלרוי.", ["חי"])
n("אליעד", "אליעד מחבר את המילים אלי ועד, ופירושו אלוהיי לעד, לתמיד. עד היא מילה עתיקה לזמן שאין לו סוף, כמו בצירוף לעולם ועד. אלעד הוא שם קרוב שבנוי על אותן מילים, ובשניהם החלק הראשון הוא כינוי לאלוהים.", ["אלעד"])
n("אליקים", "אליקים מחבר את המילים אל ויקים, ופירושו אלוהים יקים, יעמיד וירומם. יקים בא מהשורש ק־ו־ם, של המילים קם, קימה ותקומה. בתנ״ך אליקים בן חלקיהו היה הממונה על בית המלך בימי חזקיהו מלך יהודה.")
n("אלרוי", "אלרוי מחבר את המילים אל ורואי, ופירושו האל שרואה אותי. רואי בא מהשורש ר־א־ה, שממנו באות גם המילים ראייה, מראה ומראות. בכתיב השם נשמטה האות א של רואי, ונשאר הצליל הקצר רוי.")
n("ג'מילה", "ג'מילה היא הצורה לבנות של ג'מיל, מהמילה הערבית ליפה. היא באה מהשורש הערבי ג׳־מ־ל, שעניינו יופי, וממנו בא גם השם ג'מאל, שפירושו יופי. בערבית השורש מתאר גם התנהגות יפה ונאה, ולא רק מראה.", ["ג'מיל"])
n("גאזי", "גאזי היא מילה ערבית ללוחם, למי שיוצא למסע מלחמה. היא באה מהשורש הערבי שעניינו יציאה למסע ופשיטה. המילה עברה מהערבית גם לטורקית ולפרסית, ובהן היא שימשה תואר כבוד למצביאים.")
n("גולדי", "גולדי היא צורת חיבה של גולדה, שם יידי שבא מהמילה ביידיש גאָלד, זהב, הקרובה למילה הגרמנית ולמילה האנגלית בעלות אותו פירוש. הסיומת ־י מוסיפה לשם נימה של חיבה, כמו בצורות חיבה רבות בעברית וביידיש.", ["גולדה"])
n("דלאל", "דלאל היא מילה ערבית לפינוק, ליחס רך ואוהב שניתן למי שקרוב ללב. בערבית המילה מתארת גם חן ושובבות של מי שמתפנק ויודע שאוהבים אותו. היא באה מהשורש הערבי ד־ל־ל.")
n("זאהר", "זאהר היא מילה ערבית לבהיר ולגלוי, למה שנראה לעין בלי שום הסתרה. מאותו שורש באה גם המילה הערבית לצהריים, שעת האור המלא של היום, והיא קרובה למילה העברית צהריים.")
n("זינאלדין", "זינאלדין הוא שם ערבי שמחבר את המילים זין, יופי וקישוט, ואלדין, הדת. פירושו יופי הדת, או הקישוט של הדת. המילה דין פירושה בערבית דת ואמונה, ובביטוי יום אלדין היא מתארת גם יום הדין. באותה דרך נבנה גם השם עזאלדין.")
n("חי", "חי היא מילה עברית למי שנושם, צומח וקיים, ומאותו שורש באות גם המילים חיים, חיות ומחיה. בעברית של היום הצירוף חי וקיים מתאר מי ששלם ופעיל, וחי הוא גם מי שמלא מרץ ותנועה. מאותה מילה נבנו גם השמות חיים וחיה.", ["חיים", "חיה"])
n("טאלב", "טאלב היא מילה ערבית למי שמבקש ומחפש, ובעיקר לתלמיד, מי שמבקש ידע. היא באה מהשורש הערבי ט־ל־ב, שעניינו בקשה ודרישה, וממנו באה גם המילה הערבית טלב, בקשה. בערבית של היום טאלב היא המילה הרגילה לסטודנט.")
n("טלאור", "טלאור מחבר את המילים טל ואור, ופירושו טל של אור. טל הוא טיפות המים הקטנות שמופיעות על העשב ועל העלים בשעות הבוקר, והן נוצצות באור השמש. מהמילים טל ואור נבנו גם שמות אחרים, כמו טליה, אורי ואוריה.")
n("יוגב", "יוגב היא מילה עתיקה לאיכר, למי שעובד את האדמה ומגדל בה תבואה. בתנ״ך היא מופיעה בצורת הרבים יוגבים, לצד הכורמים, אנשים שעובדים בכרמים. בעברית של היום יוגב הוא גם שמו של מושב בעמק יזרעאל.")
n("יוסרא", "יוסרא היא מילה ערבית לקלות ולשפע, למצב שבו דברים נעשים בלי קושי. היא באה מהשורש הערבי י־ס־ר, שעניינו קלות ונוחות, וממנו נבנו גם יאסר ותייסיר. בערבית ההפך שלה הוא עוסרא, קושי ומצוקה.")
n("יורם", "יורם מחבר את המילים יו ורם, ופירושו ה׳ רם, נעלה ומרומם. יו היא צורה קצרה של שם ה׳, כמו בתחילת השמות יונתן ויואב. רם בא מהשורש ר־ו־ם, של המילים רום, רוממות ומרומים, והשם רם נבנה על אותה מילה.", ["רם"])
n("ליטל", "ליטל מחבר את המילים לי וטל, ופירושו יש לי טל. טל הוא טיפות המים הקטנות שמופיעות בבוקר על העשב, והוא חשוב לצמחים בארץ, שבה הקיץ ארוך ויבש. באותה דרך נבנו שמות נוספים שמתחילים במילה לי, כמו לירון וליאור.")
n("מאירה", "מאירה היא הצורה לבנות של מאיר, מהשורש א־ו־ר, ופירושה מי שנותנת אור. מאותו שורש באות גם המילים אור, מאור ותאורה. בעברית מאיר הוא גם תיאור של פנים שמחות, כמו בצירוף פנים מאירות.", ["מאיר"])
n("מירי", "מירי היא צורת חיבה קצרה של מרים, עם הסיומת ־י, שמוסיפה לשם נימה של קרבה. מרים הוא שם עתיק, ומקור המילה אינו ודאי: יש שקושרים אותו למילה מר, ויש שקושרים אותו לשפה המצרית העתיקה.", ["מרים"])
n("מנסור", "מנסור היא מילה ערבית למנצח, למי שזכה לעזרה ולניצחון. היא באה מהשורש הערבי נ־ס־ר, שעניינו עזרה וניצחון, וממנו באה גם המילה הערבית נסר, ניצחון. מאותו שורש נבנה גם השם נאסר.")
n("נהורה", "נהורה היא המילה הארמית לאור, והיא קרובה למילה העברית נהרה, אור רך וזוהר. בארמית של התלמוד נהורא היא המילה הרגילה לאור, ומכאן גם הכינוי סגי נהור, שפירושו מלא אור, לאדם עיוור.")
n("נעים", "נעים היא מילה עברית וגם מילה ערבית, ובשתי השפות היא מתארת דבר שעושה טוב ללב ולחושים. היא באה מהשורש נ־ע־ם, שממנו באות גם המילים נעימות ונעימה. מאותו שורש נבנו גם נועם, נעמה ונעמי.")
n("סברי", "סברי היא מילה ערבית לסבלני, למי שיודע לחכות ולשאת קושי בשקט. היא באה מהשורש הערבי צ־ב־ר, שעניינו סבלנות, ומאותו שורש באה המילה הערבית צבאר, הצמח הקוצני שבעברית נקרא צבר.")
n("סוג'וד", "סוג'וד היא מילה ערבית להשתחוות בתפילה, כשהמתפלל כורע ומניח את המצח על הקרקע. היא באה מהשורש הערבי ס־ג׳־ד, שממנו באה גם המילה מסגד, מקום התפילה. השורש קרוב לשורש העברי ס־ג־ד, של הפועל לסגוד.")
n("עזאלדין", "עזאלדין הוא שם ערבי שמחבר את המילים עז, כבוד וגבורה, ואלדין, הדת. פירושו כבוד הדת. המילה עז קרובה למילה העברית עוז, כוח ותעצומות. באותה דרך נבנו שמות ערביים נוספים שמסתיימים במילה אלדין, כמו זינאלדין.")
n("עמרו", "עמרו הוא שם ערבי עתיק, שהיה מוכר כבר לפני האסלאם. מקובל לקשר אותו לשורש הערבי ע־מ־ר, שעניינו חיים ויישוב של מקום. בכתב הערבי נוספת לשם אות ו בסופו, שאינה נהגית ובאה להבדיל אותו מהשם עומר, ומכאן הכתיב עמרו בעברית.")
n("רייאן", "רייאן הוא כתיב אחר של ריאן וראיין, שם ערבי שפירושו מי שרווה ושופע. הוא בא מהשורש הערבי ר־ו־י, שעניינו שתייה ורוויה, והוא קרוב לשורש העברי של המילים רוויה ורוויון. בעברית כותבים את השם בכמה דרכים, וכולן אותו שם ערבי.", ["ריאן", "ראיין"])
n("רנין", "רנין היא מילה ערבית לצליל מצלצל, כמו של פעמון או של כלי מתכת. בערבית היא מתארת גם קול צלול ונעים, שנשמע היטב למרחוק. השורש הערבי ר־נ־ן קרוב לשורש העברי של המילים רינה ורננה, שגם הן קשורות לקול ולשירה.")
n("אבנר", "אבנר הוא צורה מקוצרת של אבינר, שפירושו אבי הוא אור. נר היא מילה עתיקה לאור ולמנורה קטנה שבוערת בשמן. בתנ״ך אבנר בן נר הוא שר הצבא של שאול המלך, ושמו נכתב פעם אחת גם בצורה המלאה אבינר.")
n("אלאורי", "אלאורי מחבר את המילים אל ואורי, ופירושו אלוהים הוא האור שלי. אורי בנוי על המילה אור, והסיומת ־י מוסיפה לו את המשמעות שלי. אלאור ואליאור נבנו על אותן מילים, ומהמילה אור נבנו גם אורי ואוריאל.", ["אלאור", "אליאור"])
n("אלמאס", "אלמאס היא המילה הערבית ליהלום, אבן יקרה שקופה ונוצצת. המילה מוכרת גם בפרסית, בטורקית ובשפות נוספות, ומקובל לקשר אותה למילה היוונית אדמס, שפירושה דבר שאי אפשר לשבור. מאותה מילה יוונית באה גם המילה האנגלית ליהלום.")
n("אסעד", "אסעד בא מהשורש הערבי ס־ע־ד, שעניינו אושר והצלחה, והוא צורה שבערבית מבטאת מידה גבוהה, כמו המאושר מכולם. מאותו שורש נבנו גם סעד, סעיד ומסעוד, וגם סועאד, לבנות.")
n("בילי", "בילי היא צורת חיבה אנגלית של ויליאם, שם גרמני עתיק שמחבר את המילים רצון וקסדה, ומקובל לפרש אותו כמגן נחוש. באנגלית נבנו לויליאם כמה כינויי חיבה, ובהם ויל, ביל ובילי.", ["ויליאם"])
n("ברוריה", "ברוריה בנויה על השורש ב־ר־ר, שבעברית עניינו טוהר וניקיון, כמו בצירוף בר לבב, ובסופה הסיומת ־יה, אחד מכינויי ה׳. מאותו שורש באות גם המילים ברור ובירור. בתלמוד ברוריה היא אישה חכמה מתקופת המשנה.")
n("בתול", "בתול הוא שם ערבי לבנות, ופירושו טוהר ותום. השם בא מהשורש הערבי ב־ת־ל, והוא קרוב למילה העברית בתולה, שבעברית העתיקה פירושה נערה צעירה. בערבית מאותו שורש באה גם המילה תבתול, התמסרות שלמה.")
n("ג'בר", "ג'בר היא מילה ערבית לחיזוק ולתיקון, ובעיקר לחיבור מחדש של דבר שנשבר. היא באה מהשורש הערבי ג׳־ב־ר, וממנה באה המילה אלגברה, שפירושה בערבית איחוי של חלקים שבורים. מאותו שורש נבנה גם השם ג'אבר, מי שמחזק ומתקן.")
n("גדליה", "גדליה מחבר את המילים גדל ויה, ופירושו ה׳ גדול. הוא בא מהשורש ג־ד־ל, של המילים גדול, גודל וגדולה. בתנ״ך גדליה בן אחיקם מונה על ידי מלך בבל לשלוט ביהודה אחרי חורבן בית ראשון, ועל שמו נקרא צום גדליה, שחל אחרי ראש השנה.")
